def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_last, opp_last = history[-1]

    # Endgame: defect in last 3 rounds
    if 100 - n <= 3:
        return 'D'

    # Count opponent defections
    opp_def_total = 0
    for _, o in history:
        if o == 'D':
            opp_def_total += 1

    # Recent opponent defections (last 10)
    recent_len = 10 if n >= 10 else n
    opp_def_recent = 0
    for i in range(n - recent_len, n):
        if history[i][1] == 'D':
            opp_def_recent += 1

    # If opponent is defecting a lot, defect
    if opp_def_total >= 3 and opp_def_total * 2 > n:
        return 'D'
    if opp_def_recent >= 3:
        return 'D'

    # Tf2T: defect if opponent defected last two rounds
    if n >= 2 and history[-1][1] == 'D' and history[-2][1] == 'D':
        return 'D'

    # If opponent just defected and has a moderate defection rate, retaliate
    if opp_last == 'D' and opp_def_total >= 2 and opp_def_total * 3 > n:
        return 'D'

    # Probing logic
    probes = 0
    retaliations = 0
    last_probe_idx = -1
    for i in range(n):
        if history[i][0] == 'D':
            # Check if this was a probe: opponent's previous action was C
            if i == 0 or history[i-1][1] == 'C':
                probes += 1
                last_probe_idx = i
                if i + 1 < n and history[i+1][1] == 'D':
                    retaliations += 1

    if probes == 0:
        gap = 4
    else:
        ret_rate = retaliations / probes
        if ret_rate > 0.5:
            gap = 15
        elif ret_rate > 0.25:
            gap = 8
        else:
            gap = 4

    if last_probe_idx == -1:
        rounds_since = n
    else:
        rounds_since = n - last_probe_idx - 1

    if rounds_since >= gap and opp_last == 'C':
        return 'D'

    return 'C'
